/bin/zsh -lc "python3 - <<'PY'
from duration import parse_duration

valid = {
    \"1h30m\": 5400, \" 2d 4h \": 187200, \"1.5h\": 5400,
    \"1w2d3h4m5s\": 788645, \"1:02:03\": 3723, \"1:30\": 90,
    \"90:00\": 5400, \"-45s\": -45, \"-1:30\": -90,
    \"0\": 0, \"-0s\": 0, \"0.3m\": 18,
}
for text, expected in valid.items():
    assert parse_duration(text) == expected, text
for text in [\"\", \" \", \".5h\", \"5.h\", \"1 h\", \"1  2s\", \"30m1h\", \"1h1h\", \"0.3s\", \"1:60\", \"1:5\", \"+1h\", \"5\", \"1.5\", \"1\\t2s\"]:
    try:
        parse_duration(text)
    except ValueError:
        pass
    else:
        raise AssertionError(text)
try:
    parse_duration(None)
except TypeError:
    pass
else:
    raise AssertionError(\"None\")
print(\"duration checks passed\")
PY
python3 -m py_compile duration.py"

